<?php
namespace App\Http\Controllers; use App\Domain\Payments\Models\PaymentIntent; use App\Domain\Payments\Models\Refund; use App\Services\TilopayProvider; use App\Support\PaymentProviderResolver; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class InternalPaymentController extends Controller { public function create(Request $r){$d=$r->validate(['source'=>'required|in:store,ticketing','external_reference'=>'required|string|max:120','amount'=>'required|integer|min:1','currency'=>'required|string|size:3','provider'=>'nullable|in:tilopay,cash','metadata'=>'nullable|array']);$key=$r->header('Idempotency-Key');abort_unless($key,400,'Idempotency-Key requerido.');$old=DB::table('idempotency_keys')->where('key',$key)->first();if($old)return response()->json(json_decode($old->response,true));$providerName=$d['provider']??'tilopay';$p=PaymentIntent::create($d+['public_id'=>(string)Str::uuid(),'status'=>'created','correlation_id'=>$r->attributes->get('correlation_id')]);$result=PaymentProviderResolver::resolve($providerName)->create($d);$p->update(['provider'=>$providerName,'provider_reference'=>$result['reference'],'status'=>$result['status']]);$out=['id'=>$p->public_id,'status'=>$p->status,'provider_reference'=>$p->provider_reference,'checkout_url'=>$result['checkout_url']??null];DB::table('idempotency_keys')->insert(['key'=>$key,'operation'=>'payment.create','response'=>json_encode($out),'created_at'=>now(),'updated_at'=>now()]);return response()->json($out,201);}
 public function show(string $id){return PaymentIntent::where('public_id',$id)->firstOrFail();} public function cancel(string $id){$p=PaymentIntent::where('public_id',$id)->firstOrFail();abort_unless(in_array($p->status,['created','pending','requires_action']),409,'Estado no cancelable.');$p->update(['status'=>'cancelled']);return $p;} public function confirmCash(Request $r,string $id){$p=PaymentIntent::where('public_id',$id)->firstOrFail();abort_unless($p->provider==='cash',409,'Este intent no es de efectivo.');if($p->status==='succeeded')return response()->json(['id'=>$p->public_id,'status'=>$p->status]);abort_if(in_array($p->status,['cancelled']),409,'Estado no confirmable.');$p->update(['status'=>'succeeded','metadata'=>array_merge($p->metadata??[],['cash_confirmed_by'=>$r->input('confirmed_by'),'cash_confirmed_at'=>now()->toIso8601String()])]);return response()->json(['id'=>$p->public_id,'status'=>$p->status]);} public function refund(Request $r,string $id){$p=PaymentIntent::where('public_id',$id)->firstOrFail();$d=$r->validate(['amount'=>'required|integer|min:1|max:'.$p->amount]);$key=$r->header('Idempotency-Key');abort_unless($key,400,'Idempotency-Key requerido.');$old=DB::table('idempotency_keys')->where('key',$key)->first();if($old)return response()->json(json_decode($old->response,true));$res=app(TilopayProvider::class)->refund($p->provider_reference,$d['amount'],$p->currency);$ref=Refund::create(['public_id'=>(string)Str::uuid(),'payment_intent_id'=>$p->id,'amount'=>$d['amount'],'currency'=>$p->currency,'status'=>$res['status'],'provider_reference'=>$p->provider_reference]);$out=['id'=>$ref->public_id,'status'=>$ref->status];DB::table('idempotency_keys')->insert(['key'=>$key,'operation'=>'refund.create','response'=>json_encode($out),'created_at'=>now(),'updated_at'=>now()]);return response()->json($out,201);} public function refundShow(string $id){return Refund::where('public_id',$id)->firstOrFail();} public function transactions(string $id){return DB::table('provider_transactions')->where('id',$id)->firstOrFail();} public function reconciliations(){return DB::table('reconciliations')->latest()->paginate(50);} }
